def length_of_lis(nums, k):
    n = len(nums)
    dp = [1] * n
    for i in range(n):
        for j in range(i):                              # scan every earlier element directly
            if nums[j] < nums[i] and nums[i] - nums[j] <= k:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

