class SegTree:
    def __init__(self, size):
        self.n = size
        self.tree = [0] * (4 * (size + 1))

    def update(self, node, start, end, idx, val):
        if start == end:
            self.tree[node] = max(self.tree[node], val)
            return
        mid = (start + end) // 2
        if idx <= mid:
            self.update(2 * node + 1, start, mid, idx, val)
        else:
            self.update(2 * node + 2, mid + 1, end, idx, val)
        self.tree[node] = max(self.tree[2 * node + 1], self.tree[2 * node + 2])

    def query(self, node, start, end, l, r):
        if r < start or end < l or l > r:
            return 0
        if l <= start and end <= r:
            return self.tree[node]
        mid = (start + end) // 2
        return max(self.query(2 * node + 1, start, mid, l, r),
                   self.query(2 * node + 2, mid + 1, end, l, r))


def length_of_lis(nums, k):
    max_val = max(nums)
    seg = SegTree(max_val)
    best = 0
    for num in nums:
        lo, hi = max(0, num - k), num - 1
        prev_best = seg.query(0, 0, max_val, lo, hi) if hi >= lo else 0   # range-max query, O(log maxVal)
        length = prev_best + 1
        best = max(best, length)
        seg.update(0, 0, max_val, num, length)                            # point update, O(log maxVal)
    return best

