        int mid = (start + end) / 2;
        if (idx <= mid) update(2 * node + 1, start, mid, idx, val);
        else update(2 * node + 2, mid + 1, end, idx, val);
        tree[node] = Math.max(tree[2 * node + 1], tree[2 * node + 2]);
    }

    static int query(int node, int start, int end, int l, int r) {
        if (r < start || end < l || l > r) return 0;
        if (l <= start && end <= r) return tree[node];
        int mid = (start + end) / 2;
        return Math.max(query(2 * node + 1, start, mid, l, r), query(2 * node + 2, mid + 1, end, l, r));
    }

    static int lengthOfLIS(int[] nums, int k) {
        int maxVal = 0;
        for (int x : nums) maxVal = Math.max(maxVal, x);
        tree = new int[4 * (maxVal + 1)];
        int best = 0;
        for (int num : nums) {
            int lo = Math.max(0, num - k), hi = num - 1;
            int prevBest = hi >= lo ? query(0, 0, maxVal, lo, hi) : 0;   // range-max query
            int length = prevBest + 1;
            best = Math.max(best, length);
            update(0, 0, maxVal, num, length);                             // point update
        }
        return best;
    }
