}

int query(int node, int start, int end, int l, int r) {
    if (r < start || end < l || l > r) return 0;
    if (l <= start && end <= r) return tree[node];
    int mid = (start + end) / 2;
    return max(query(2 * node + 1, start, mid, l, r), query(2 * node + 2, mid + 1, end, l, r));
}

